const mk=(id,s,n,type,est,req,d,pre)=>({id,s,n,type,est,st:'open',req,steps:Object.assign({explain:0,solve:0,review:0},pre||{}),notes:'',hist:[{t:Date.now(),m:'إنشاء المهمة'}],d,c:Date.now()});
function seed(s){const have=new Set(s.tasks.map(t=>t.id)),n={};let c=0;
W.forEach((wk,wi)=>wk.forEach((day,di)=>day.forEach(([k,q])=>{
if(typeof q==='string'){const id='x'+wi+di;if(!have.has(id)){s.tasks.push(mk(id,'x',q,'مراجعة',120,[],wi*7+di));c++}return}
for(let i=0;i<q;i++){n[k]=(n[k]||0)+1;const id='b'+k+n[k];if(!have.has(id)){s.tasks.push(mk(id,k,S[k][0]+' – محاضرة '+n[k],'تراكم',150,(k=='ar'||k=='ge')?['explain','solve','review']:['explain','review'],wi*7+di));c++}}})));
[['e1','الوحدة 1 – فيديوهات (شوهدت بحسب الطالب)',{explain:1}],['e2','الوحدة 2 – فيديوهات (شوهدت بحسب الطالب)',{explain:1}],['e3a','الوحدة 3 – درس كبير 1 (تقدير تقريبي)'],['e3b','الوحدة 3 – درس كبير 2 (تقدير تقريبي)'],['e3c','الوحدة 3 – درس كبير 3 (تقدير تقريبي)']].forEach(([id,nm,p])=>{if(!have.has(id)){s.tasks.push(mk(id,'en',nm,'إنجليزي',150,['explain','solve','review'],null,p));c++}});return c}
const def=()=>{const s={v:1,pv:3,rel:0,tasks:[],sess:[],set:{start:iso(new Date()),st30:1,mode:'manual',manual:240,bed:'23:00',wake:'07:00',auto:0,sleep:480,meals:120,pray:90,rest:120,other:360},tm:{dur:25,left:1500,run:0,end:0,task:''},
q:{rd:[],hf:[],rv:[],wird:5},pt:{},prayed:{},dh:[['d1','سبحان الله'],['d2','الحمد لله'],['d3','الله أكبر'],['d4','أستغفر الله']].map(([id,n])=>({id,n,c:0,g:33})),rev:[]};return s};
let st,tab='today',pw=0,qt='rd',err=0;
function load(){try{const r=localStorage.getItem(KEY);if(r){const o=JSON.parse(r);if(valid(o)){st=Object.assign(def(),o);st.set=Object.assign(def().set,o.set);st.q=Object.assign(def().q,o.q);return}}}catch(e){err=1}st=def()}
function save(){try{localStorage.setItem(KEY,JSON.stringify(st));return 1}catch(e){err=1;toast('تعذّر الحفظ في هذا المتصفح. صدّر نسخة من قسم البيانات.','e');return 0}}
function valid(o){return o&&typeof o=='object'&&Array.isArray(o.tasks)&&o.tasks.every(t=>t&&typeof t.id=='string'&&typeof t.n=='string'&&S[t.s]&&['open','done'].includes(t.st)&&typeof t.est=='number'&&t.steps&&Array.isArray(t.req)&&Array.isArray(t.hist))&&(!o.q||typeof o.q=='object')}
function toast(m,k){const t=Q('#to');t.textContent=m;t.style.background=k=='e'?'var(--rd)':'var(--ok)';t.style.display='block';clearTimeout(toast.h);toast.h=setTimeout(()=>t.style.display='none',2800)}
const today0=()=>{const d=new Date();d.setHours(0,0,0,0);return d},off=()=>Math.round((today0()-new Date(st.set.start+'T00:00'))/864e5),net=()=>{const s=st.set;if(s.mode!='auto')return Math.max(0,+s.manual||0);const q=t=>{const p=(t||'0:0').split(':');return +p[0]*60+ +p[1]},sl=(q(s.wake)-q(s.bed)+1440)%1440;return Math.max(0,1440-sl-s.meals-s.pray-s.rest-s.other)},fm=m=>Math.floor(m/60)+'س '+m%60+'د';
const dateOf=o=>{const d=new Date(st.set.start+'T00:00');d.setDate(d.getDate()+o);return d.toLocaleDateString('ar',{weekday:'short',day:'numeric',month:'short'})};
const ld=o=>st.tasks.filter(t=>t.st=='open'&&t.d===o).reduce((a,t)=>a+t.est,0);
const lbl=o=>o<0?'قبل بداية الخطة':'الأسبوع '+(Math.floor(o/7)+1)+' · اليوم '+(o%7+1)+(o%7>4?' (يوم الجديد)':'');
const bar=p=>`<div class="bar"><i style="width:${Math.min(100,p)}%"></i></div>`;
const chip=t=>`<span class="c" style="background:${S[t.s][2]}">${S[t.s][0]}</span>`;
function TL(a,em){return a.length?a.map(t=>{const o=off(),late=t.st=='open'&&t.d!=null&&t.d<o;return`<div class="t ${t.st}" onclick="A.open('${t.id}')"><span class="ck" onclick="event.stopPropagation();A.done('${t.id}')">${t.st=='done'?'✓':''}</span>${chip(t)}<div class="n">${E(t.n)}<div class="m">${t.type} · ${t.est} د${t.d!=null?' · '+dateOf(t.d):''}</div></div>${late?'<span class="bd late">متأخرة</span>':''}${t.st=='done'?'<span class="bd okc">تمّت</span>':''}</div>`}).join(''):`<div class="e">${em||'لا مهام هنا.'}</div>`}
function qa(){const cur=Math.max(0,Math.min(3,Math.floor(off()/7))),cap=2*net(),m={};let w=cur,u=0;
st.tasks.filter(t=>t.type=='جديد'&&t.st=='open').sort((a,b)=>S[a.s][1]-S[b.s][1]||a.c-b.c).forEach(t=>{if(u&&u+t.est>cap){w++;u=0}m[t.id]=w>3?0:w+1;u+=t.est});return m}
function streak(){const s=new Set(st.sess.map(x=>x.day));st.tasks.forEach(t=>{if(t.doneAt)s.add(iso(new Date(t.doneAt)))});let n=0,d=today0();if(!s.has(iso(d)))d.setDate(d.getDate()-1);while(s.has(iso(d))){n++;d.setDate(d.getDate()-1)}return n}
function xp(){return st.tasks.filter(t=>t.st=='done').length*50+st.sess.reduce((a,x)=>a+x.min,0)+(uq(st.q.rd)+uq(st.q.hf))*2}
function badges(){const d=st.tasks.filter(t=>t.st=='done').length,m=st.sess.reduce((a,x)=>a+x.min,0),K=['ar','ge','ca','ph','ch'],sub=k=>{const a=st.tasks.filter(t=>t.s==k&&t.type!='جديد');return a.length>0&&a.every(t=>t.st=='done')},s=streak();
return[['🌱','أول مهمة',d>=1],['🔟','10 مهام',d>=10],['🔥','3 أيام متتالية',s>=3],['⚡','7 أيام متتالية',s>=7],['⏱','5 ساعات تركيز',m>=300],['📖','50 صفحة قراءة',uq(st.q.rd)>=50],['🏁','أنهيت مادة',K.some(sub)],['🏆','كل التراكمات',K.every(sub)]]}
function confetti(){for(let i=0;i<32;i++){const s=document.createElement('i');s.className='cf';s.style.cssText=`left:${Math.random()*100}vw;background:hsl(${Math.random()*360},80%,58%);animation-delay:${Math.random()*.35}s`;document.body.appendChild(s);setTimeout(()=>s.remove(),2000)}}
function mig2(){if(st.pv>=2)return;const D={bch1:14,bch2:14,bch3:15,bch4:16,bch5:17,bch6:18,bch7:18,bch8:21,bch9:21,bch10:22,bch11:22,e3a:17,e3b:19,e3c:20};
st.tasks.forEach(t=>{if(t.st=='open'&&D[t.id]!=null&&!t.hist.some(h=>/جدولة|ضبط/.test(h.m)))t.d=D[t.id]});
[['x06','اختبار ومراجعة الأخطاء',6],['x16','اختبار أسبوعي',13]].forEach(([id,n,d])=>{if(!st.tasks.some(t=>t.id==id))st.tasks.push(mk(id,'x',n,'مراجعة',90,[],d))});st.pv=2}
function mig3(){if(st.pv>=3)return;const D={e3a:4,e3b:11,e3c:17,e1:18,e2:25};st.tasks.forEach(t=>{if(t.st=='open'&&D[t.id]!=null&&!t.hist.some(h=>/جدولة|ضبط/.test(h.m)))t.d=D[t.id]});st.pv=3}
function autoNew(){if(!st.set.auto)return 0;const wp=Math.min(Math.floor(off()/7),52);let c=0;
while(st.rel<wp){st.rel++;['en','ph','ar','ch','ma'].forEach(k=>{const id='a'+st.rel+k;if(!st.tasks.some(t=>t.id==id)){const t=mk(id,k,S[k][0]+' – محاضرة جديدة (نهاية أسبوع '+st.rel+')','جديد',((st.sd||{})[k]||150),['explain','solve','review'],null);t.hist[0].m='نزلت تلقائيًا مع نهاية الأسبوع '+st.rel;st.tasks.push(t);c++}})}return c}
function exm(){const e=st.set.exam;if(!e)return'';const d=Math.round((new Date(e+'T00:00')-today0())/864e5);if(d<0)return`<div class='bx nx'><b>انتهى موعد الامتحان</b><div class='m'>غيّر التاريخ من الإعدادات.</div></div>`;const rem=st.tasks.filter(t=>t.st=='open').reduce((a,t)=>a+t.est,0),per=Math.ceil(rem/Math.max(1,d)),n=net();return`<div class='bx nx'><b>⏳ الامتحان بعد ${d} يوم</b><div class='m'>المتبقي ${fm(rem)} ← تحتاج حوالي ${fm(per)} يوميًا والمتاح ${fm(n)}</div>${per>n?`<div class='w'>الوقت لا يكفي بهذا الإيقاع. ارفع الوقت المتاح أو قلّل المهام.</div>`:`<div class='m'>إيقاعك يكفي إن التزمت.</div>`}</div>`}
function pr(){const n=new Date(),now=n.getHours()*60+n.getMinutes(),L=PR.filter(([i])=>st.pt[i]).map(([i,nm])=>{const p=st.pt[i].split(':');return[nm,st.pt[i],+p[0]*60+ +p[1]]});if(!L.length)return'';let x=L.find(p=>p[2]>now),d;if(x)d=x[2]-now;else{x=L[0];d=x[2]+1440-now}return`<div class='bx'><b>🕌 ${x[0]} ${x[1]}</b><div class='m'>بعد ${fm(d)} (من المواقيت التي كتبتها أنت)</div></div>`}
function hdr(){try{const e=st.set.exam,th=st.set.theme,d=document.documentElement;if(d){if(th=='light'||th=='dark')d.dataset.theme=th;else delete d.dataset.theme}{const b=document.body;if(b&&b.dataset){b.dataset.bg=st.set.bg||'arch';b.style.backgroundColor=st.set.bg=='color'?(st.set.bgc||''):''}}const hp=Q('#hp');if(hp){const n=e?Math.ceil((new Date(e+'T00:00')-new Date())/864e5):null;hp.textContent=n==null?'خطة 2027 · تراكمات ودروس وورد':n>=0?'⏳ '+n+' يوم على الامتحان':'انتهى موعد الامتحان'}}catch(x){}}
function exm(){const e=st.set.exam;if(!e)return'';const ex=new Date(e+'T00:00'),ms=ex-new Date();if(ms<0)return`<div class='bx nx'><b>انتهى موعد الامتحان</b><div class='m'>غيّر التاريخ من الإعدادات.</div></div>`;const d=Math.floor(ms/864e5),h=Math.floor(ms/36e5)%24,s0=new Date(st.set.start+'T00:00'),p=Math.max(0,Math.min(1,1-ms/Math.max(1,ex-s0))),rem=st.tasks.filter(t=>t.st=='open').reduce((a,t)=>a+t.est,0),per=Math.ceil(rem/Math.max(1,d+1)),n=net(),C=2*Math.PI*34;
return`<div class='bx cd'><svg viewBox='0 0 80 80' width='96' height='96'><circle cx='40' cy='40' r='34' fill='none' stroke='var(--ln)' stroke-width='7'/><circle cx='40' cy='40' r='34' fill='none' stroke='var(--gd)' stroke-width='7' stroke-linecap='round' stroke-dasharray='${(C*p).toFixed(1)} ${C.toFixed(1)}' transform='rotate(-90 40 40)'/><text x='40' y='47' text-anchor='middle' font-size='22' font-weight='600' fill='currentColor'>${d}</text></svg><div><b>باقي ${d} يوم و${h} ساعة</b><div class='m'>${Math.round(p*100)}% من رحلتك مضى</div><div class='m'>المتبقي ${fm(rem)} ← حوالي ${fm(per)} يوميًا (المتاح ${fm(n)})</div>${per>n?`<div class='w'>الوقت لا يكفي بهذا الإيقاع.</div>`:`<div class='m' style='color:var(--ok)'>إيقاعك يكفي إن التزمت ✓</div>`}</div></div>`}
function nxt(td,od){const t=od.concat(td).sort((p,q)=>S[p.s][1]-S[q.s][1])[0];return t?`<div class="bx nx"><div class="m">التالي بحسب الأولوية</div><b>${E(t.n)}</b><div class="m">${S[t.s][0]} · ${t.est} د</div><button class="b" onclick="A.focusOn('${t.id}')">ابدأ الآن</button><button class="b g" onclick="A.open('${t.id}')">تفاصيل</button></div>`:`<div class="bx nx"><b>🎉 لا مهام معلّقة اليوم</b><div class="m">راجع أخطاءك أو افتح قسم الجديد.</div></div>`}
